+import { $internal } from '../common';
+import type { Trait } from '../trait/types';
+import type { Aspect, AspectRecord, AspectTraits, AspectValue } from './types';
+
+let aspectId = 0;
+
+export function isAspect(value: unknown): value is Aspect {
+    return (value as Aspect | undefined)?.__aspect === true;
+}
+
+export function createAspect<T extends AspectTraits>(...inputs: T): Aspect<T> {
+    const traits: Trait[] = [];
+    const fields = new Set<string>();
+
+    for (const input of inputs) {
+        const nested = isAspect(input) ? input.traits : [input];
+        for (const trait of nested) {
+            if (trait[$internal].relation) {
+                throw new Error('Aspects cannot contain relation traits.');
+            }
+
+            const schema = trait.schema;
+            if (typeof schema !== 'function') {
+                for (const field of Object.keys(schema)) {
+                    if (fields.has(field)) {
+                        throw new Error(`Aspect traits cannot share the field "${field}".`);
+                    }
+                    fields.add(field);
+                }
+            }
+            traits.push(trait);
+        }
+    }
+
+    if (traits.length < 2) throw new Error('An aspect requires at least two traits.');
+
+    const id = aspectId++;
+    const aspect = Object.assign(
+        (value?: AspectValue<Aspect<T>>) => [aspect, value ?? {}],
+        {
+            id,
+            traits: traits as unknown as T,
+            schema: Object.fromEntries(
+                traits.flatMap((trait) =>
+                    typeof trait.schema === 'function' ? [] : Object.entries(trait.schema)
+                )
+            ),
+            __aspect: true as const,
+        }
+    ) as Aspect<T>;
+
+    return aspect;
+}
+
+export function splitAspectValue(aspect: Aspect, value: Record<string, any>) {
+    return aspect.traits.map((trait) => {
+        const schema = trait.schema;
+        if (typeof schema === 'function') return value;
+        const part: Record<string, any> = {};
+        for (const field of Object.keys(schema)) {
+            if (field in value) part[field] = value[field];
+        }
+        return part;
+    });
+}
+
+export function mergeAspectValues<T extends Aspect>(
+    aspect: T,
+    values: unknown[]
+): AspectRecord<T['traits']> {
+    return Object.assign({}, ...values) as AspectRecord<T['traits']>;
+}
